chart:
"use client"

import {
  ChartContainer,
  ChartTooltip,
  ChartTooltipContent,
} from "@/components/ui/chart"
import { Bar, BarChart, CartesianGrid, XAxis } from "recharts"

const chartData = [
  { month: "Jan", usage: 38 },
  { month: "Feb", usage: 56 },
  { month: "Mar", usage: 68 },
  { month: "Apr", usage: 82 },
]
const chartConfig = { usage: { label: "Usage", color: "var(--color-primary)" } }

export function Example() {
  return (
    <ChartContainer config={chartConfig} className="h-36 w-full max-w-xs">
      <BarChart accessibilityLayer data={chartData}>
        <CartesianGrid vertical={false} />
        <XAxis
          dataKey="month"
          tickLine={false}
          axisLine={false}
          tickMargin={8}
        />
        <ChartTooltip
          cursor={false}
          content={<ChartTooltipContent hideLabel />}
        />
        <Bar dataKey="usage" fill="var(--color-usage)" radius={6} />
      </BarChart>
    </ChartContainer>
  )
}

